"use client";

import Popover from "@/components/ui/popover";
import type { PopoverPlacement } from "@/components/ui/popover";

const placements: PopoverPlacement[] = [
  "top-start",
  "top",
  "top-end",
  "left",
  "right",
  "bottom-start",
  "bottom",
  "bottom-end",
];

export default function PopoverPlacementsDemo() {
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(3, auto)",
        gap: "var(--may-space-3)",
        placeItems: "center",
        padding: "var(--may-space-16)",
        background: "var(--may-color-bg, var(--background))",
      }}
    >
      {placements.map((placement) => (
        <Popover
          key={placement}
          placement={placement}
          aria-label={placement}
          trigger={
            <button
              type="button"
              style={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                height: "var(--may-control-h-sm)",
                padding: "0 var(--may-space-3)",
                borderRadius: "var(--may-radius-sm)",
                border: 0,
                background: "var(--may-color-fill-quaternary)",
                color: "var(--may-color-text)",
                fontSize: "var(--may-text-footnote)",
                cursor: "pointer",
              }}
            >
              {placement}
            </button>
          }
        >
          <span
            style={{
              whiteSpace: "nowrap",
              fontSize: "var(--may-text-subheadline)",
              color: "var(--may-color-text)",
            }}
          >
            Anchored {placement}
          </span>
        </Popover>
      ))}
    </div>
  );
}
